 const teamCounts=new Map;for(const x of people){let name=teamName(x.team_id);if(name==='—'){const m=String(x.department||'').match(/الفريق\s*([^•]+)/);if(m)name='فريق '+m[1].trim()}if(name!=='—')teamCounts.set(name,(teamCounts.get(name)||0)+1)}
